// ============================================
// VALIDADOR DE HORARIOS SCHEMA.ORG PARA N8N
// Soporta múltiples items y zona horaria Colombia
// ============================================

const items = $input.all();
const resultados = [];

// IMPORTANTE: Definir zona horaria de Colombia
const TIMEZONE = 'America/Bogota';

for (const item of items) {
  const horario = item.json.horarios || item.json.horario; // Soporta ambos nombres

  // Obtener fecha y hora actual EN COLOMBIA
  const ahoraUTC = new Date();
  const ahoraColombia = new Date(ahoraUTC.toLocaleString('en-US', { timeZone: TIMEZONE }));

  const diasSemana = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];
  const diaActual = diasSemana[ahoraColombia.getDay()];
  const minutosActuales = ahoraColombia.getHours() * 60 + ahoraColombia.getMinutes();

  // Si no hay horario definido = cerrado
  if (!horario || horario.trim() === '') {
    resultados.push({
      json: {
        ...item.json,
        esta_abierto: false,
        estado: 'Sin horario definido'
      }
    });
    continue;
  }

  // Parsear bloques separados por coma y punto y coma
  const bloques = horario.split(/[,;]/).map(b => b.trim());
  let horarioEncontrado = null;

  for (const bloque of bloques) {
    const partes = bloque.split(' ');

    // Si solo hay días sin horario = abierto todo el día
    if (partes.length === 1) {
      const dias = partes[0];
      if (verificarDia(dias, diaActual)) {
        horarioEncontrado = '00:00-23:59';
        break;
      }
      continue;
    }

    // Formato normal: "Mo-Fr 11:00-22:00"
    const dias = partes[0];
    const horas = partes[1];

    if (verificarDia(dias, diaActual)) {
      horarioEncontrado = horas;
      break;
    }
  }

  // Si no se encontró el día = cerrado
  if (!horarioEncontrado) {
    resultados.push({
      json: {
        ...item.json,
        esta_abierto: false,
        estado: 'Cerrado hoy',
        mensaje: 'No abre los ' + traducirDia(diaActual)
      }
    });
    continue;
  }

  // Parsear horario de apertura y cierre
  const [apertura, cierre] = horarioEncontrado.split('-');
  const minutosApertura = horaAMinutos(apertura);
  const minutosCierre = horaAMinutos(cierre);

  // CASO ESPECIAL: Cierre después de medianoche (ej: 18:00-02:00)
  let estaAbierto;

  if (minutosCierre < minutosApertura) {
    // Cruza medianoche
    estaAbierto = minutosActuales >= minutosApertura || minutosActuales < minutosCierre;
  } else {
    // Horario normal en el mismo día
    estaAbierto = minutosActuales >= minutosApertura && minutosActuales < minutosCierre;
  }

  // Calcular mensaje descriptivo
  let mensaje = '';
  if (estaAbierto) {
    let minHastaCierre;

    if (minutosCierre < minutosApertura) {
      // Cruza medianoche
      if (minutosActuales >= minutosApertura) {
        // Estamos en el día de apertura
        minHastaCierre = (1440 - minutosActuales) + minutosCierre;
      } else {
        // Estamos en el día siguiente
        minHastaCierre = minutosCierre - minutosActuales;
      }
    } else {
      // Mismo día
      minHastaCierre = minutosCierre - minutosActuales;
    }

    const horas = Math.floor(minHastaCierre / 60);
    const mins = minHastaCierre % 60;
    mensaje = `Abierto - Cierra en ${horas}h ${mins}min`;
  } else {
    if (minutosActuales < minutosApertura) {
      const minHastaApertura = minutosApertura - minutosActuales;
      const horas = Math.floor(minHastaApertura / 60);
      const mins = minHastaApertura % 60;
      mensaje = `Cerrado - Abre en ${horas}h ${mins}min`;
    } else {
      mensaje = 'Cerrado - Abrirá mañana';
    }
  }

  resultados.push({
    json: {
      ...item.json,
      esta_abierto: estaAbierto,
      estado: estaAbierto ? 'Abierto' : 'Cerrado',
      mensaje: mensaje,
      horario_hoy: horarioEncontrado,
      dia_actual: traducirDia(diaActual),
      hora_actual: `${ahoraColombia.getHours()}:${String(ahoraColombia.getMinutes()).padStart(2, '0')}`
    }
  });
}

return resultados;

// ============================================
// FUNCIONES AUXILIARES
// ============================================

function verificarDia(expresionDias, diaActual) {
  // Rangos: Mo-Fr
  if (expresionDias.includes('-')) {
    const [inicio, fin] = expresionDias.split('-');
    const ordenDias = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];
    const idxInicio = ordenDias.indexOf(inicio);
    const idxFin = ordenDias.indexOf(fin);
    const idxActual = ordenDias.indexOf(diaActual);

    if (idxInicio <= idxFin) {
      return idxActual >= idxInicio && idxActual <= idxFin;
    } else {
      // Rango que cruza semana (ej: Sa-Mo)
      return idxActual >= idxInicio || idxActual <= idxFin;
    }
  }

  // Múltiples días: Mo,We,Fr
  return expresionDias.split(',').map(d => d.trim()).includes(diaActual);
}

function horaAMinutos(hora) {
  const [h, m] = hora.split(':').map(Number);
  return h * 60 + m;
}

function traducirDia(dia) {
  const traducciones = {
    'Mo': 'lunes',
    'Tu': 'martes',
    'We': 'miércoles',
    'Th': 'jueves',
    'Fr': 'viernes',
    'Sa': 'sábado',
    'Su': 'domingo'
  };
  return traducciones[dia] || dia;
}
